import requests

def client(host=RESTAPI_SERVER_HOST, port=RESTAPI_SERVER_PORT):
    addr = 'http://%s:%d' % (host, port)
    logger.info("Starting REST-JSON API client to '%s'..." % addr)
    logger.info('Using requests to interact with the API.')
    response = requests.get(f'{addr}/task/new')
    if response.status_code == 200:
        taskid = response.json().get('taskid')
        logger.info(f'Created new task with id: {taskid}')
    else:
        logger.error('Failed to create a new task.')
        return
    scan_data = {'url': 'http://testphp.vulnweb.com/artists.php?artist=1'}
    response = requests.post(f'{addr}/scan/{taskid}/start', json=scan_data)
    if response.status_code == 200:
        logger.info('Scan started successfully.')
    else:
        logger.error('Failed to start scan.')
    response = requests.get(f'{addr}/scan/{taskid}/data')
    if response.status_code == 200:
        logger.info('Scan data retrieved successfully.')
    else:
        logger.error('Failed to retrieve scan data.')
    response = requests.get(f'{addr}/scan/{taskid}/log')
    if response.status_code == 200:
        logger.info('Scan log retrieved successfully.')
    else:
        logger.error('Failed to retrieve scan log.')

import re

def _obfuscate_command(self, command_args: Sequence[CommandArg], obfuscate_args: Optional[Iterable[CommandArg]]=None) -> ObfuscatedCommand:
    obfuscate_args = set(chain(obfuscate_args or [], self.default_obfuscation))
    obfuscated = ' '.join((self.obfuscation if any((re.match(arg.pattern, str(command_arg)) for arg in obfuscate_args)) else shlex.quote(str(command_arg)) for command_arg in command_args))
    return ObfuscatedCommand(obfuscated)

