def __init__(self, app, pubsub, *message_types):
    self.PubSub = pubsub
    self.Loop = app.Loop
    for message_type in message_types:
        self.PubSub.subscribe(message_type, self._on_message)
    self.Websockets = set([])

    async def cleanup(self):
        for ws in self.Websockets:
            await ws.close(code=WSCloseCode.GOING_AWAY, message='Server shutdown')
    self.Loop.add_signal_handler(signal.SIGTERM, self.cleanup)

def api_acl_get(packagename=None):
    packagename = flask.request.args.get('packagename', None) or packagename
    httpcode = 200
    if packagename:
        acl_data = retrieve_acl_for_package(packagename)
        if acl_data:
            output = {'output': 'ok', 'acl': acl_data}
        else:
            output = {'output': 'notok', 'error': 'ACL not found'}
            httpcode = 404
    else:
        output = {'output': 'notok', 'error': 'Invalid request'}
        httpcode = 500
    jsonout = flask.jsonify(output)
    jsonout.status_code = httpcode
    return jsonout

