def create_from_list(self, data, constructor, error):
    result = []
    names = [x for x in map(str.strip, re.split('[, ]+', data)) if x]
    for name in names:
        result.append(constructor(name))
    return set(result)

def transform(self, X, y=None):
    X = check_array(X)
    if self.mean_ is not None:
        X = X - self.mean_
    X = safe_sparse_dot(X, self.components_.T)
    return X

def is_sharded(self):
    from corehq.sql_db.models import PartitionedModel
    return issubclass(self.model_class, PartitionedModel)

def user_permissions(self, create, extracted, **kwargs):
    if not create:
        return
    if extracted:
        for permission in extracted:
            if isinstance(permission, str):
                try:
                    (label, codename) = permission.split('.')
                except ValueError:
                    label = ''
                    codename = permission
                filters = {'codename': codename}
                if label:
                    filters['content_type__app_label'] = label
                permission = Permission.objects.get(**filters)
            self.user_permissions.add(permission)

def deleteModulePort(self, module_id, port_tuple):
    self.emit(QtCore.SIGNAL('flushMoveActions()'))
    module = self.currentPipeline.getModuleById(module_id)
    spec_id = -1
    for (i, port_spec) in enumerate(module.port_specs):
        if port_spec.type == port_tuple[0] and port_spec.name == port_tuple[1]:
            spec_id = i
            break
    if spec_id == -1:
        return False
    port_spec = module.port_specs[spec_id]
    action = db.services.action.create_action([('delete', port_spec, module.vtType, module.id)])
    self.vistrail.add_action(action, self.currentVersion)
    return self.perform_action(action)

